convention.template:
# Debug Session: {feature-slug}

## Summary
{one-line conclusion}

## Steps

### Step {n}: {action}
- **Action**: {description}
- **Expected**: {what should happen}
- **Observed**: {what actually happened}
- **Console**: {relevant console output}
- **Network**: {relevant network activity}
- **Screenshot**: {path}
- **Verdict**: {PASS / FAIL / INVESTIGATE}

## Root Cause
{identified issue or "inconclusive"}

// 1. Browser setup
const browser = await playwright.chromium.launch({ headless: false });
const context = await browser.newContext({ viewport: { width: 1280, height: 720 } });
const page = await context.newPage();

// 2. Register listeners
page.on('console', msg => console.log(`[${msg.type()}] ${msg.text()}`));
page.on('pageerror', err => console.log(`[PAGE ERROR] ${err}`));
page.on('requestfailed', req => console.log(`[FAILED] ${req.url()}`));

// 3. Navigate and capture
await page.goto(url, { waitUntil: 'networkidle' });
await page.screenshot({ path: 'evidence/00-baseline.png' });

// 4. Interact and capture
await page.getByRole('button').click();
await page.waitForLoadState('networkidle');
await page.screenshot({ path: 'evidence/01-after-click.png' });

// 5. Verify
const computedStyle = await page.evaluate(() => {
  const el = document.querySelector('.target');
  return { color: getComputedStyle(el).color, display: getComputedStyle(el).display };
});

principle.code_template:
// Correct approach — exact computation
const contrast = await page.evaluate(() => {
  const el = document.querySelector('.card-text');
  const fg = getComputedStyle(el).color;         // e.g. "rgb(33, 37, 41)"
  const bg = getComputedStyle(el).backgroundColor; // e.g. "rgb(45, 45, 68)"
  const ratio = wcagContrast(fg, bg);              // e.g. 1.36
  return { ratio, passesAA: ratio >= 4.5 };
});

principle.measurement:
const spacing = await page.evaluate(() => {
  const cards = document.querySelectorAll('.card, .panel, [class*="card"], [class*="panel"]');
  return Array.from(cards).map(c => ({
    padding: getComputedStyle(c).padding,
    margin: getComputedStyle(c).margin,
    borderRadius: getComputedStyle(c).borderRadius,
  }));
});

principle.computation:
const paletteCheck = await page.evaluate(() => {
  const elements = document.querySelectorAll('*');
  const colors = new Set();
  elements.forEach(el => {
    const bg = getComputedStyle(el).backgroundColor;
    const color = getComputedStyle(el).color;
    if (bg && bg !== 'rgba(0, 0, 0, 0)') colors.add(bg);
    if (color && color !== 'rgba(0, 0, 0, 0)') colors.add(color);
  });
  // Convert each color to HSL, group by hue proximity
  // Flag if more than 3 distinct hue families exist
  // Flag if lightness steps are inconsistent
  return { paletteSize: colors.size, /* hueClusters, lightnessSteps */ };
});
